/// Check if in given vector of numbers, are any two numbers closer to each other than
/// given threshold.
/// >>> has_close_elements(vec![1.0, 2.0, 3.0], 0.5)
/// false
/// >>> has_close_elements(vec![1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
/// true
fn has_close_elements(numbers: Vec<f64>, threshold: f64) -> bool {
    if numbers.len() < 2 {
        return false;
    }
    let mut sorted = numbers;
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    for i in 0..sorted.len() - 1 {
        if (sorted[i + 1] - sorted[i]).abs() < threshold {
            return true;
        }
    }
    false
}

fn separate_paren_groups(paren_string: String) -> Vec<String> {
    let mut result: Vec<String> = Vec::new();
    let mut current: Vec<char> = Vec::new();
    let mut depth: i32 = 0;

    for c in paren_string.chars() {
        if c == ' ' {
            continue;
        }
        if c == '(' {
            depth += 1;
            current.push(c);
        } else if c == ')' {
            depth -= 1;
            current.push(c);
            if depth == 0 {
                result.push(current.iter().collect());
                current.clear();
            }
        }
    }

    result
}

/// Given a positive floating point number, it can be decomposed into
/// and integer part (largest integer smaller than given number) and decimals
/// (leftover part always smaller than 1).
/// Return the decimal part of the number.
/// >>> truncate_number(3.5)
/// 0.5
fn truncate_number(number: f64) -> f64 {
    number - number.floor()
}

/// You're given a vector of deposit and withdrawal operations on a bank account that starts with
/// zero balance. Your task is to detect if at any point the balance of account fallls below zero, and
/// at that point function should return true. Otherwise it should return false.
/// >>> below_zero(vec![1, 2, 3])
/// false
/// >>> below_zero(vec![1, 2, -4, 5])
/// true
fn below_zero(operations: Vec<isize>) -> bool {
    let mut balance: isize = 0;
    for op in operations {
        balance += op;
        if balance < 0 {
            return true;
        }
    }
    false
}

/// For a given vector of input numbers, calculate Mean Absolute Deviation
/// around the mean of this dataset.
/// Mean Absolute Deviation is the average absolute difference between each
/// element and a centerpoint (mean in this case):
/// MAD = average | x - x_mean |
/// >>> mean_absolute_deviation(vec![1.0, 2.0, 3.0, 4.0])
/// 1.0
fn mean_absolute_deviation(numbers: Vec<f64>) -> f64 {
    if numbers.is_empty() {
        return 0.0;
    }
    let n = numbers.len() as f64;
    let mean = numbers.iter().sum::<f64>() / n;
    let sum_abs_dev: f64 = numbers.iter().map(|x| (x - mean).abs()).sum();
    sum_abs_dev / n
}

/// Insert a number 'delimeter' between every two consecutive elements of input vector `numbers'
/// >>> intersperse(vec![], 4)
/// Vec::<isize>::new()
/// >>> intersperse(vec![1, 2, 3], 4)
/// vec![1, 4, 2, 4, 3]
fn intersperse(numbers: Vec<isize>, delimeter: isize) -> Vec<isize> {
    if numbers.is_empty() {
        return Vec::new();
    }
    let mut result = Vec::with_capacity(numbers.len() * 2 - 1);
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num);
        if i + 1 < numbers.len() {
            result.push(delimeter);
        }
    }
    result
}

fn parse_nested_parens(paren_string: String) -> Vec<isize> {
    let mut result = Vec::new();
    for group in paren_string.split_whitespace() {
        let mut max_depth: isize = 0;
        let mut current_depth: isize = 0;
        for ch in group.chars() {
            match ch {
                '(' => {
                    current_depth += 1;
                    if current_depth > max_depth {
                        max_depth = current_depth;
                    }
                }
                ')' => {
                    current_depth -= 1;
                }
                _ => {}
            }
        }
        result.push(max_depth);
    }
    result
}

fn filter_by_substring(strings: Vec<String>, substring: String) -> Vec<String> {
    strings.into_iter().filter(|s| s.contains(&substring)).collect()
}

/// For a given vector of integers, return a tuple consisting of a sum and a product of all the integers in a vector.
/// Empty sum should be equal to 0 and empty product should be equal to 1.
/// >>> sum_product(vec![])
/// (0, 1)
/// >>> sum_product(vec![1, 2, 3, 4])
/// (10, 24)
fn sum_product(numbers: Vec<isize>) -> (isize, isize) {
    let sum = numbers.iter().sum::<isize>();
    let product = numbers.iter().product::<isize>();
    (sum, product)
}

/// From a given vector of integers, generate a vector of rolling maximum element found until given moment
/// in the sequence.
/// >>> rolling_max(vec![1, 2, 3, 2, 3, 4, 2])
/// vec![1, 2, 3, 3, 3, 4, 4]
fn rolling_max(numbers: Vec<isize>) -> Vec<isize> {
    let mut result = Vec::with_capacity(numbers.len());
    let mut current_max = isize::MIN;
    for &num in &numbers {
        if num > current_max {
            current_max = num;
        }
        result.push(current_max);
    }
    result
}

fn make_palindrome(string: String) -> String {
    if string.is_empty() {
        return string;
    }

    let chars: Vec<char> = string.chars().collect();
    let n = chars.len();

    // Find the longest suffix that is a palindrome
    // We check from the full string down to length 1
    for i in 0..n {
        // Check if chars[i..] is a palindrome
        let mut is_palindrome = true;
        let start = i;
        let end = n - 1;
        let mut left = start;
        let mut right = end;
        while left < right {
            if chars[left] != chars[right] {
                is_palindrome = false;
                break;
            }
            left += 1;
            right -= 1;
        }
        if is_palindrome {
            // The prefix before the palindromic suffix is chars[0..i]
            // We need to append the reverse of this prefix to the end
            let prefix: Vec<char> = chars[0..i].to_vec();
            let mut result: Vec<char> = chars.clone();
            for c in prefix.iter().rev() {
                result.push(*c);
            }
            return result.into_iter().collect();
        }
    }

    // If no palindromic suffix found (shouldn't happen since a single char is always a palindrome),
    // append the reverse of the entire string
    let mut result: Vec<char> = chars.clone();
    for c in chars.iter().rev() {
        result.push(*c);
    }
    result.into_iter().collect()
}

/// Input are two strings a and b consisting only of 1s and 0s.
/// Perform binary XOR on these inputs and return result also as a string.
/// >>> string_xor(String::from("010"), String::from("110"))
/// String::from("100")
fn string_xor(a: String, b: String) -> String {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let len = a_chars.len().max(b_chars.len());
    let mut result = String::with_capacity(len);
    for i in 0..len {
        let a_bit = if i < a_chars.len() { a_chars[i] } else { '0' };
        let b_bit = if i < b_chars.len() { b_chars[i] } else { '0' };
        let xor = if a_bit == b_bit { '0' } else { '1' };
        result.push(xor);
    }
    result
}

fn longest(strings: Vec<String>) -> Option<String> {
    strings.into_iter().max_by_key(|s| s.len())
}

/// Return a greatest common divisor of two integers a and b
/// >>> greatest_common_divisor(3, 5)
/// 1
/// >>> greatest_common_divisor(25, 15)
/// 5
fn greatest_common_divisor(a: isize, b: isize) -> isize {
    let mut a = a.abs();
    let mut b = b.abs();
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

/// Return vector of all prefixes from shortest to longest of the input string
/// >>> all_prefixes(String::from("abc"))
/// vec![String::from("a"), String::from("ab"), String::from("abc")]
fn all_prefixes(string: String) -> Vec<String> {
    let len = string.len();
    (1..=len)
        .map(|i| string[..i].to_string())
        .collect()
}

/// Return a string containing space-delimited numbers starting from 0 upto n inclusive.
/// >>> string_sequence(0)
/// String::from("0")
/// >>> string_sequence(5)
/// String::from("0 1 2 3 4 5")
fn string_sequence(n: isize) -> String {
    if n < 0 {
        return String::new();
    }
    (0..=n)
        .map(|i| i.to_string())
        .collect::<Vec<String>>()
        .join(" ")
}

fn count_distinct_characters(string: String) -> isize {
    let mut seen: std::collections::HashSet<char> = std::collections::HashSet::new();
    for c in string.chars() {
        if c.is_alphabetic() {
            seen.insert(c.to_ascii_lowercase());
        }
    }
    seen.len() as isize
}

fn parse_music(music_string: String) -> Vec<isize> {
    let mut result: Vec<isize> = Vec::new();
    let chars: Vec<char> = music_string.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == 'o' {
            if i + 1 < chars.len() && chars[i + 1] == '|' {
                result.push(2);
                i += 2;
            } else {
                result.push(4);
                i += 1;
            }
        } else if chars[i] == '.' {
            if i + 1 < chars.len() && chars[i + 1] == '|' {
                result.push(1);
                i += 2;
            } else {
                // Should not happen based on the spec, but skip
                i += 1;
            }
        } else {
            // Skip spaces or any other characters
            i += 1;
        }
    }
    result
}

fn how_many_times(string: String, substring: String) -> isize {
    if substring.is_empty() {
        return 0;
    }
    let s = string.as_str();
    let sub = substring.as_str();
    let s_len = s.len();
    let sub_len = sub.len();
    if sub_len > s_len {
        return 0;
    }
    let mut count: isize = 0;
    for i in 0..=(s_len - sub_len) {
        if &s[i..i + sub_len] == sub {
            count += 1;
        }
    }
    count
}

fn sort_numbers(numbers: String) -> String {
    let word_to_num: &[(u8, &str)] = &[
        (0, "zero"),
        (1, "one"),
        (2, "two"),
        (3, "three"),
        (4, "four"),
        (5, "five"),
        (6, "six"),
        (7, "seven"),
        (8, "eight"),
        (9, "nine"),
    ];

    let words: Vec<&str> = numbers.split_whitespace().collect();
    let mut pairs: Vec<(u8, &str)> = Vec::new();

    for word in words {
        for &(num, w) in word_to_num {
            if word == w {
                pairs.push((num, word));
                break;
            }
        }
    }

    pairs.sort_by_key(|&(num, _)| num);

    pairs.iter().map(|&(_, w)| w).collect::<Vec<_>>().join(" ")
}

fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut sorted = numbers;
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let mut min_diff = f64::INFINITY;
    let mut result = (sorted[0], sorted[1]);

    for i in 0..sorted.len() - 1 {
        let diff = sorted[i + 1] - sorted[i];
        if diff < min_diff {
            min_diff = diff;
            result = (sorted[i], sorted[i + 1]);
        }
    }

    result
}

fn rescale_to_unit(numbers: Vec<f64>) -> Vec<f64> {
    let min_val = numbers.iter().cloned().fold(f64::INFINITY, f64::min);
    let max_val = numbers.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let range = max_val - min_val;
    if range == 0.0 {
        return vec![0.0; numbers.len()];
    }
    numbers.iter().map(|&x| (x - min_val) / range).collect()
}

