/// For a given number n, find the largest number that divides n evenly, smaller than n
/// >>> largest_divisor(15)
/// 5
fn largest_divisor(n: isize) -> isize {
    if n == 0 {
        return 0;
    }
    let abs_n = n.abs();
    if abs_n == 1 {
        return 1;
    }
    // Find the smallest divisor greater than 1
    let mut i: isize = 2;
    while i * i <= abs_n {
        if abs_n % i == 0 {
            return abs_n / i;
        }
        i += 1;
    }
    // If no divisor found, n is prime, so the largest divisor smaller than n is 1
    1
}

fn factorize(n: isize) -> Vec<isize> {
    let mut factors = Vec::new();
    let mut n = n;

    // Handle negative numbers by factoring the absolute value
    if n < 0 {
        n = -n;
    }

    // Handle 0 and 1
    if n == 0 || n == 1 {
        return factors;
    }

    // Factor out 2s
    while n % 2 == 0 {
        factors.push(2);
        n /= 2;
    }

    // Factor out odd numbers starting from 3
    let mut divisor = 3;
    while divisor * divisor <= n {
        while n % divisor == 0 {
            factors.push(divisor);
            n /= divisor;
        }
        divisor += 2;
    }

    // If n is still greater than 1, then it's a prime factor
    if n > 1 {
        factors.push(n);
    }

    factors
}

use std::collections::HashMap;

/// From a vector of integers, remove all elements that occur more than once.
/// Keep order of elements left the same as in the input.
/// >>> remove_duplicates(vec![1, 2, 3, 2, 4])
/// vec![1, 3, 4]
fn remove_duplicates(numbers: Vec<isize>) -> Vec<isize> {
    let mut counts: HashMap<isize, usize> = HashMap::new();
    for &num in &numbers {
        *counts.entry(num).or_insert(0) += 1;
    }
    numbers
        .into_iter()
        .filter(|&num| counts[&num] == 1)
        .collect()
}

/// For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
/// >>> flip_case(String::from("Hello"))
/// String::from("hELLO")
fn flip_case(string: String) -> String {
    string
        .chars()
        .map(|c| {
            if c.is_lowercase() {
                c.to_uppercase().to_string()
            } else if c.is_uppercase() {
                c.to_lowercase().to_string()
            } else {
                c.to_string()
            }
        })
        .collect()
}

/// Concatenate vector of strings into a single string
/// >>> concatenate(vec![])
/// String::from("")
/// >>> concatenate(vec![String::from("a"), String::from("b"), String::from("c")])
/// String::from("abc")
fn concatenate(strings: Vec<String>) -> String {
    strings.join("")
}

/// Filter an input vector of strings only for ones that start with a given prefix.
/// >>> filter_by_prefix(vec![], String::from("a"))
/// Vec::<String>::new()
/// >>> filter_by_prefix(vec![String::from("abc"), String::from("bcd"), String::from("cde"), String::from("array")], String::from("a"))
/// vec![String::from("abc"), String::from("array")]
fn filter_by_prefix(strings: Vec<String>, prefix: String) -> Vec<String> {
    strings
        .into_iter()
        .filter(|s| s.starts_with(&prefix))
        .collect()
}

/// Return only positive numbers in the vector.
/// >>> get_positive(vec![-1, 2, -4, 5, 6])
/// vec![2, 5, 6]
/// >>> get_positive(vec![5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10])
/// vec![5, 3, 2, 3, 9, 123, 1]
fn get_positive(l: Vec<isize>) -> Vec<isize> {
    l.into_iter().filter(|&x| x > 0).collect()
}

fn is_prime(n: isize) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

fn sort_third(l: Vec<isize>) -> Vec<isize> {
    let mut result = l.clone();
    // Collect indices divisible by 3
    let indices: Vec<usize> = (0..result.len()).filter(|&i| i % 3 == 0).collect();
    // Extract values at those indices
    let mut values: Vec<isize> = indices.iter().map(|&i| result[i]).collect();
    // Sort the values
    values.sort();
    // Put them back
    for (idx, &i) in indices.iter().enumerate() {
        result[i] = values[idx];
    }
    result
}

/// Return sorted unique elements in a vector
/// >>> unique(vec![5, 3, 5, 2, 3, 3, 9, 0, 123])
/// vec![0, 2, 3, 5, 9, 123]
fn unique(l: Vec<isize>) -> Vec<isize> {
    let mut set: std::collections::BTreeSet<isize> = l.into_iter().collect();
    set.into_iter().collect()
}

/// Return maximum element in the vector.
/// >>> max_element(vec![1, 2, 3])
/// 3
/// >>> max_element(vec![5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10])
/// 123
fn max_element(l: Vec<isize>) -> isize {
    *l.iter().max().unwrap()
}

/// Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
/// >>> fizz_buzz(50)
/// 0
/// >>> fizz_buzz(78)
/// 2
/// >>> fizz_buzz(79)
/// 3
fn fizz_buzz(n: isize) -> isize {
    let mut count: isize = 0;
    for i in 0..n {
        if i % 11 == 0 || i % 13 == 0 {
            let s = i.to_string();
            for c in s.chars() {
                if c == '7' {
                    count += 1;
                }
            }
        }
    }
    count
}

fn sort_even(l: Vec<isize>) -> Vec<isize> {
    let mut result = l.clone();
    let mut even_values: Vec<isize> = result.iter().enumerate().filter(|(i, _)| i % 2 == 0).map(|(_, v)| *v).collect();
    even_values.sort();
    let mut idx = 0;
    for i in (0..result.len()).step_by(2) {
        result[i] = even_values[idx];
        idx += 1;
    }
    result
}

fn prime_fib(n: isize) -> isize {
    fn is_prime(num: isize) -> bool {
        if num < 2 {
            return false;
        }
        if num == 2 {
            return true;
        }
        if num % 2 == 0 {
            return false;
        }
        let mut i = 3;
        while i * i <= num {
            if num % i == 0 {
                return false;
            }
            i += 2;
        }
        true
    }

    let mut count = 0;
    let mut a: isize = 0;
    let mut b: isize = 1;
    loop {
        let next = a + b;
        a = b;
        b = next;
        if is_prime(a) {
            count += 1;
            if count == n {
                return a;
            }
        }
    }
}

fn triples_sum_to_zero(l: Vec<isize>) -> bool {
    let n = l.len();
    if n < 3 {
        return false;
    }
    let mut sorted = l;
    sorted.sort();
    for i in 0..n - 2 {
        let mut j = i + 1;
        let mut k = n - 1;
        while j < k {
            let sum = sorted[i] + sorted[j] + sorted[k];
            if sum == 0 {
                return true;
            } else if sum < 0 {
                j += 1;
            } else {
                k -= 1;
            }
        }
    }
    false
}

/// Imagine a road that's a perfectly straight infinitely long line.
/// n cars are driving left to right;  simultaneously, a different set of n cars
/// are driving right to left.   The two sets of cars start out being very far from
/// each other.  All cars move in the same speed.  Two cars are said to collide
/// when a car that's moving left to right hits a car that's moving right to left.
/// However, the cars are infinitely sturdy and strong; as a result, they continue moving
/// in their trajectory as if they did not collide.
/// This function outputs the number of such collisions.
fn car_race_collision(n: isize) -> isize {
    n * n
}

