fn pairs_sum_to_zero(l: Vec<isize>) -> bool {
    use std::collections::HashSet;
    let mut seen = HashSet::new();
    for &x in &l {
        if seen.contains(&(-x)) {
            return true;
        }
        seen.insert(x);
    }
    false
}

/// Change numerical base of input number x to base.
/// return string representation after the conversion.
/// base numbers are less than 10.
/// >>> change_base(8, 3)
/// String::from("22")
/// >>> change_base(8, 2)
/// String::from("1000")
/// >>> change_base(7, 2)
/// String::from("111")
fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return "0".to_string();
    }

    let mut result = String::new();
    let mut n = x;

    while n != 0 {
        let digit = (n % base) as u8;
        result.insert(0, (b'0' + digit) as char);
        n /= base;
    }

    result
}

/// Given length of a side and high return area for a triangle.
/// >>> triangle_area(5, 3)
/// 7.5
fn triangle_area(a: isize, h: isize) -> f64 {
    0.5 * a as f64 * h as f64
}

fn fib4(n: isize) -> isize {
    if n < 0 {
        return 0;
    }
    let n = n as usize;
    if n == 0 || n == 1 {
        return 0;
    }
    if n == 2 {
        return 2;
    }
    if n == 3 {
        return 0;
    }
    let mut a: isize = 0; // fib4(0)
    let mut b: isize = 0; // fib4(1)
    let mut c: isize = 2; // fib4(2)
    let mut d: isize = 0; // fib4(3)
    for i in 4..=n {
        let next = a + b + c + d;
        a = b;
        b = c;
        c = d;
        d = next;
    }
    d
}

fn median(l: Vec<isize>) -> f64 {
    if l.is_empty() {
        return 0.0;
    }
    let mut sorted = l;
    sorted.sort_unstable();
    let n = sorted.len();
    if n % 2 == 1 {
        sorted[n / 2] as f64
    } else {
        (sorted[n / 2 - 1] as f64 + sorted[n / 2] as f64) / 2.0
    }
}

/// Checks if given string is a palindrome
/// >>> is_palindrome(String::from(""))
/// true
/// >>> is_palindrome(String::from("aba"))
/// true
/// >>> is_palindrome(String::from("aaaaa"))
/// true
/// >>> is_palindrome(String::from("zbcd"))
/// false
fn is_palindrome(text: String) -> bool {
    let chars: Vec<char> = text.chars().collect();
    let len = chars.len();
    for i in 0..len / 2 {
        if chars[i] != chars[len - 1 - i] {
            return false;
        }
    }
    true
}

fn modp(n: isize, p: isize) -> isize {
    if p == 1 {
        return 0;
    }
    let mut result: isize = 1;
    let mut base: isize = 2 % p;
    let mut exp: isize = n;
    while exp > 0 {
        if exp & 1 == 1 {
            result = (result * base) % p;
        }
        base = (base * base) % p;
        exp >>= 1;
    }
    result
}

fn remove_vowels(text: String) -> String {
    text.chars()
        .filter(|c| !matches!(c.to_ascii_lowercase(), 'a' | 'e' | 'i' | 'o' | 'u'))
        .collect()
}

/// Return true if all numbers in the vector l are below threshold t.
/// >>> below_threshold(vec![1, 2, 4, 10], 100)
/// true
/// >>> below_threshold(vec![1, 20, 4, 10], 5)
/// false
fn below_threshold(l: Vec<isize>, t: isize) -> bool {
    l.iter().all(|&x| x < t)
}

/// Add two numbers x and y
/// >>> add(2, 3)
/// 5
/// >>> add(5, 7)
/// 12
fn add(x: isize, y: isize) -> isize {
    x + y
}

fn same_chars(s0: String, s1: String) -> bool {
    let chars0: std::collections::HashSet<char> = s0.chars().collect();
    let chars1: std::collections::HashSet<char> = s1.chars().collect();
    chars0 == chars1
}

/// Return n-th Fibonacci number.
/// >>> fib(10)
/// 55
/// >>> fib(1)
/// 1
/// >>> fib(8)
/// 21
fn fib(n: isize) -> isize {
    if n <= 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }
    let mut a: isize = 0;
    let mut b: isize = 1;
    for _ in 2..=n {
        let c = a + b;
        a = b;
        b = c;
    }
    b
}

fn correct_bracketing(brackets: String) -> bool {
    let mut depth: i32 = 0;
    for c in brackets.chars() {
        match c {
            '<' => depth += 1,
            '>' => {
                depth -= 1;
                if depth < 0 {
                    return false;
                }
            }
            _ => {}
        }
    }
    depth == 0
}

/// Return true is vector elements are monotonically increasing or decreasing.
/// >>> monotonic(vec![1, 2, 4, 20])
/// true
/// >>> monotonic(vec![1, 20, 4, 10])
/// false
/// >>> monotonic(vec![4, 1, 0, -10])
/// true
fn monotonic(l: Vec<isize>) -> bool {
    if l.len() <= 2 {
        return true;
    }
    let increasing = l.windows(2).all(|w| w[0] <= w[1]);
    let decreasing = l.windows(2).all(|w| w[0] >= w[1]);
    increasing || decreasing
}

fn common(l1: Vec<isize>, l2: Vec<isize>) -> Vec<isize> {
    use std::collections::HashSet;
    let set1: HashSet<isize> = l1.into_iter().collect();
    let set2: HashSet<isize> = l2.into_iter().collect();
    let mut result: Vec<isize> = set1.intersection(&set2).cloned().collect();
    result.sort();
    result
}

fn largest_prime_factor(n: isize) -> isize {
    let mut n = n;
    let mut largest = 1;

    // Divide out all factors of 2
    while n % 2 == 0 {
        largest = 2;
        n /= 2;
    }

    // Check odd factors from 3 up to sqrt(n)
    let mut i: isize = 3;
    while i * i <= n {
        while n % i == 0 {
            largest = i;
            n /= i;
        }
        i += 2;
    }

    // If n is still greater than 1, then it's a prime factor
    if n > 1 {
        largest = n;
    }

    largest
}

/// sum_to_n is a function that sums numbers from 1 to n.
/// >>> sum_to_n(30)
/// 465
/// >>> sum_to_n(100)
/// 5050
/// >>> sum_to_n(5)
/// 15
/// >>> sum_to_n(10)
/// 55
/// >>> sum_to_n(1)
/// 1
fn sum_to_n(n: isize) -> isize {
    n * (n + 1) / 2
}

fn correct_bracketing(brackets: String) -> bool {
    let mut balance: i32 = 0;
    for ch in brackets.chars() {
        match ch {
            '(' => balance += 1,
            ')' => {
                balance -= 1;
                if balance < 0 {
                    return false;
                }
            }
            _ => return false,
        }
    }
    balance == 0
}

fn derivative(xs: Vec<isize>) -> Vec<isize> {
    if xs.len() <= 1 {
        return Vec::new();
    }
    xs.iter()
        .enumerate()
        .skip(1)
        .map(|(i, &coeff)| i as isize * coeff)
        .collect()
}

fn fibfib(n: isize) -> isize {
    if n < 0 {
        return 0;
    }
    let n = n as usize;
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 0;
    }
    if n == 2 {
        return 1;
    }
    let mut a: isize = 0; // fibfib(0)
    let mut b: isize = 0; // fibfib(1)
    let mut c: isize = 1; // fibfib(2)
    for i in 3..=n {
        let next = a + b + c;
        a = b;
        b = c;
        c = next;
    }
    c
}

fn vowels_count(s: String) -> isize {
    let lower = s.to_lowercase();
    let chars: Vec<char> = lower.chars().collect();
    let mut count: isize = 0;
    for (i, c) in chars.iter().enumerate() {
        if matches!(c, 'a' | 'e' | 'i' | 'o' | 'u') {
            count += 1;
        } else if *c == 'y' && i == chars.len() - 1 {
            count += 1;
        }
    }
    count
}

fn circular_shift(x: isize, shift: isize) -> String {
    let s = x.to_string();
    let n = s.len();
    if shift > n as isize {
        s.chars().rev().collect()
    } else {
        let shift = shift as usize;
        if shift == 0 {
            s
        } else {
            let split_point = n - shift;
            let right = &s[split_point..];
            let left = &s[..split_point];
            format!("{}{}", right, left)
        }
    }
}

fn digitSum(s: String) -> isize {
    s.chars()
        .filter(|c| c.is_ascii_uppercase())
        .map(|c| c as isize)
        .sum()
}

fn fruit_distribution(s: String, n: isize) -> isize {
    // Parse the string to extract the number of apples and oranges
    // The format is: "<num> apples and <num> oranges"
    let parts: Vec<&str> = s.split_whitespace().collect();

    // parts[0] is the number of apples, parts[3] is the number of oranges
    let apples: isize = parts[0].parse().unwrap_or(0);
    let oranges: isize = parts[3].parse().unwrap_or(0);

    // The number of mangoes is the total minus apples and oranges
    n - apples - oranges
}

fn pluck(arr: Vec<isize>) -> Vec<isize> {
    let mut min_value: Option<isize> = None;
    let mut min_index: Option<isize> = None;

    for (i, &val) in arr.iter().enumerate() {
        if val % 2 == 0 {
            match min_value {
                None => {
                    min_value = Some(val);
                    min_index = Some(i as isize);
                }
                Some(mv) => {
                    if val < mv {
                        min_value = Some(val);
                        min_index = Some(i as isize);
                    }
                }
            }
        }
    }

    match (min_value, min_index) {
        (Some(v), Some(idx)) => vec![v, idx],
        _ => Vec::new(),
    }
}

fn search(lst: Vec<isize>) -> isize {
    use std::collections::HashMap;

    let mut freq: HashMap<isize, isize> = HashMap::new();
    for &x in &lst {
        *freq.entry(x).or_insert(0) += 1;
    }

    let mut best: isize = -1;
    for (&val, &count) in &freq {
        if val > 0 && count >= val {
            if val > best {
                best = val;
            }
        }
    }

    best
}

fn strange_sort_list(lst: Vec<isize>) -> Vec<isize> {
    if lst.is_empty() {
        return Vec::new();
    }
    let mut sorted: Vec<isize> = lst;
    sorted.sort();
    let mut result = Vec::with_capacity(sorted.len());
    let mut left = 0;
    let mut right = sorted.len() - 1;
    let mut take_min = true;
    while left <= right {
        if take_min {
            result.push(sorted[left]);
            left += 1;
        } else {
            result.push(sorted[right]);
            right -= 1;
        }
        take_min = !take_min;
    }
    result
}

fn triangle_area(a: isize, b: isize, c: isize) -> f64 {
    let a_f = a as f64;
    let b_f = b as f64;
    let c_f = c as f64;

    // Check if sides form a valid triangle
    if a_f <= 0.0 || b_f <= 0.0 || c_f <= 0.0 {
        return -1.0;
    }
    if a_f + b_f <= c_f || a_f + c_f <= b_f || b_f + c_f <= a_f {
        return -1.0;
    }

    // Use Heron's formula
    let s = (a_f + b_f + c_f) / 2.0;
    let area = (s * (s - a_f) * (s - b_f) * (s - c_f)).sqrt();

    // Round to 2 decimal places
    (area * 100.0).round() / 100.0
}

fn will_it_fly(q: Vec<isize>, w: isize) -> bool {
    // Check if the vector is a palindrome (balanced)
    let is_palindrome = {
        let len = q.len();
        for i in 0..len / 2 {
            if q[i] != q[len - 1 - i] {
                return false;
            }
        }
        true
    };

    if !is_palindrome {
        return false;
    }

    // Check if the sum of elements is less than or equal to w
    let sum: isize = q.iter().sum();
    sum <= w
}

fn smallest_change(arr: Vec<isize>) -> isize {
    let n = arr.len();
    let mut changes = 0;
    for i in 0..n / 2 {
        if arr[i] != arr[n - 1 - i] {
            changes += 1;
        }
    }
    changes
}

