    let total2: usize = lst2.iter().map(|s| s.chars().count()).sum();
    if total1 <= total2 {
        lst1
    } else {
        lst2
    }
}

fn is_multiply_prime(a: isize) -> bool {
    // We need to check if a is the product of exactly 3 prime numbers.
    // Since a < 100, we can brute force.
    // First, a must be positive and at least 2*2*2 = 8.
    if a < 8 {
        return false;
    }

    // Helper to check if a number is prime
    fn is_prime(n: isize) -> bool {
        if n < 2 {
            return false;
        }
        if n == 2 {
            return true;
        }
        if n % 2 == 0 {
            return false;
        }
        let mut i = 3;
        while i * i <= n {
            if n % i == 0 {
                return false;
            }
            i += 2;
        }
        true
    }

    // We need to find if there exist three primes p1, p2, p3 such that p1 * p2 * p3 == a.
    // Since a < 100, the primes are small.
    // We can iterate over possible p1 and p2, then check if p3 = a / (p1 * p2) is an integer and prime.
    // To avoid duplicates, we can assume p1 <= p2 <= p3.

    let mut p1: isize = 2;
    while p1 * p1 * p1 <= a {
        if is_prime(p1) {
            let mut p2: isize = p1;
            while p1 * p2 * p2 <= a {
                if is_prime(p2) {
                    let product = p1 * p2;
                    if a % product == 0 {
                        let p3 = a / product;
                        if p3 >= p2 && is_prime(p3) {
                            return true;
                        }
                    }
                }
                p2 += 1;
            }
        }
        p1 += 1;
    }

    false
}

fn is_simple_power(x: isize, n: isize) -> bool {
    // If x is 1, it's a simple power of any n (n^0 = 1)
    if x == 1 {
        return true;
    }
    // If x is 0, it's not a simple power (unless we consider 0^something, but 0^n for n>0 is 0, but n^0=1, so 0 can't be n^int for any int unless n=0 and int>0, but 0^0 is undefined. Let's check: if n=0, then 0^int = 0 for int>0, so x=0 could be 0^1. But the problem says n**int=x. Let's think about edge cases.)
    // Actually, let's reconsider. The examples don't include 0. Let's handle it carefully.
    // If n is 0: 0^0 is undefined, 0^1=0, 0^2=0, etc. So if x==0 and n==0, is it true? The problem says "n**int=x". For n=0, int must be >=1 to get 0. But int is an integer, could be negative? 0^(-1) is undefined. So probably int >= 0. If int=0, n^0=1 (for n!=0). For n=0, 0^0 is typically 1 in some contexts but undefined in others.
    // Let's look at the examples: is_simple_power(1, 4) = true (4^0=1). So int can be 0.
    // For n=0: 0^0 is ambiguous. Let's assume int >= 0. If n=0 and x=0, then 0^1=0, so it should be true? But 0^0 is also a question.
    // Let's check: if n=0, x=0: is 0 a simple power of 0? 0^1=0, so yes if we allow int=1.
    // If n=0, x=1: 0^0=1? If we define 0^0=1, then yes. But this is tricky.
    // Let's handle n=0 separately.
    if n == 0 {
        // 0^0 is typically considered 1 in combinatorics, but in programming it's often undefined.
        // 0^k for k>0 is 0.
        // So if x==0, then 0^1=0, so return true.
        // If x==1, then 0^0=1? Let's say false to be safe, or true?
        // The problem doesn't specify. Let's look at the pattern: for n=1, x=1 is true (1^0=1 or 1^1=1).
        // For n=0, x=0: I'll say true (0^1=0).
        // For n=0, x=1: I'll say false (0^0 is undefined or 1, but let's be conservative).
        // Actually, let's think: if n=0, the only way to get x is if x=0 (with int>=1) or x=1 (with int=0, if 0^0=1).
        // Let's return true if x==0, false otherwise for n==0.
        return x == 0;
    }
    // If n is 1: 1^int = 1 for any int. So x must be 1.
    if n == 1 {
        return x == 1;
    }
    // If n is -1: (-1)^int = 1 if int is even, -1 if int is odd. So x can be 1 or -1.
    if n == -1 {
        return x == 1 || x == -1;
    }
    // For |n| >= 2, we can iterate.
    // We need to find an integer k >= 0 such that n^k = x.
    // Start with k=0: n^0 = 1.
    // k=1: n^1 = n.
    // k=2: n^2, etc.
    // We need to be careful with negative n and negative x.
    // Let's iterate k from 0 upward, computing n^k, and check if it equals x.
    // We stop when the absolute value of n^k exceeds the absolute value of x (if x != 0).
    // But x could be negative, and n could be negative.

    // Let's handle x == 0: for |n| >= 2, n^k is never 0 for k >= 0. So return false.
    if x == 0 {
        return false;
    }

    // Now x != 0, n != 0, |n| >= 2.
    // We'll compute powers of n and check.
    let mut power = 1;
    let mut k = 0;
    loop {
        if power == x {
            return true;
        }
        // Check if we've gone too far
        // If |power| > |x| and we're increasing in magnitude, we can stop.
        // But we need to be careful with signs.
        // Let's compute the next power and check.
        // To avoid overflow, we can check if multiplying by n would exceed x in magnitude.
        // Actually, let's just compute and check for overflow.
        // Since isize can overflow, we need to be careful.

        // Let's check if power * n would overflow or if we've already exceeded x in magnitude.
        // A simpler approach: since |n| >= 2, the magnitude grows quickly. We can limit the number of iterations.
        // For isize (64-bit), the maximum power is at most 63 (for n=2, 2^63 overflows).
        // So we can iterate at most 64 times.

        if k > 63 {
            return false;
        }

        // Compute next power
        // Check for overflow: if power > 0 and n > 0 and power > isize::MAX / n, then overflow.
        // Similarly for negative cases.
        // Let's use a safe multiplication check.
        let next_power = match power.checked_mul(n) {
            Some(v) => v,
            None => {
                // Overflow, so we've gone too far
                return false;
            }
        };
        power = next_power;
        k += 1;
    }
}

fn iscube(a: isize) -> bool {
    // Handle the special case of 0
    if a == 0 {
        return true;
    }

    // Determine the sign
    let sign = if a > 0 { 1 } else { -1 };
    let abs_a = a.unsigned_abs();

    // Compute the integer cube root of abs_a
    // We need to find n such that n^3 == abs_a
    // Use binary search or just iterate

    // For efficiency, we can use a binary search approach
    // The cube root of abs_a is at most (abs_a)^(1/3)
    // For isize, the max value is around 2^63, so cube root is around 2^21

    let mut low: u64 = 0;
    let mut high: u64 = 1;

    // Find an upper bound
    while high.copied().map_or(false, |h| h.saturating_mul(h).saturating_mul(h) < abs_a) {
        high = high.saturating_mul(2);
        if high == 0 {
            // Overflow, but this shouldn't happen for valid isize inputs
            break;
        }
    }

    // Binary search for the cube root
    while low < high {
        let mid = low + (high - low) / 2;
        let mid_cubed = mid.saturating_mul(mid).saturating_mul(mid);
        if mid_cubed < abs_a {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    // Now low is the smallest integer such that low^3 >= abs_a
    // Check if low^3 == abs_a
    let candidate = low;
    let candidate_cubed = candidate.saturating_mul(candidate).saturating_mul(candidate);
    candidate_cubed == abs_a
}

fn hex_key(num: String) -> isize {
    num.chars()
        .filter(|c| matches!(c, '2' | '3' | '5' | '7' | 'B' | 'D'))
        .count() as isize
}

