    let binary = format!("{:b}", decimal);
    format!("db{}db", binary)
}

fn is_happy(s: String) -> bool {
    if s.len() < 3 {
        return false;
    }
    let chars: Vec<char> = s.chars().collect();
    for i in 0..=chars.len() - 3 {
        if chars[i] == chars[i + 1] || chars[i] == chars[i + 2] || chars[i + 1] == chars[i + 2] {
            return false;
        }
    }
    true
}

