fn prime_length(string: String) -> bool {
    let len = string.len();
    if len < 2 {
        return false;
    }
    if len == 2 {
        return true;
    }
    if len % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= len {
        if len % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

/// Given a positive integer n, return the count of the numbers of n-digit
/// positive integers that start or end with 1.
fn starts_one_ends(n: isize) -> isize {
    if n == 1 {
        return 1;
    }
    // Total n-digit numbers: 9 * 10^(n-1)
    // Numbers starting with 1: 10^(n-1)
    // Numbers ending with 1: 9 * 10^(n-2) (for n >= 2, the first digit can be 1-9, last digit is 1)
    // Numbers starting AND ending with 1: 10^(n-2) (for n >= 2, first digit is 1, last digit is 1, middle digits can be anything)
    // By inclusion-exclusion: start_with_1 + end_with_1 - both
    // = 10^(n-1) + 9 * 10^(n-2) - 10^(n-2)
    // = 10^(n-1) + 8 * 10^(n-2)
    // = 10^(n-2) * (10 + 8)
    // = 18 * 10^(n-2)
    let pow = 10isize.pow((n - 2) as u32);
    18 * pow
}

fn solve(N: isize) -> String {
    let sum: isize = N.to_string().chars().map(|c| c.to_digit(10).unwrap() as isize).sum();
    format!("{:b}", sum)
}

/// Given a non-empty vector of integers lst. add the even elements that are at odd indices..
/// Examples:
/// >>> add(vec![4, 2, 6, 7])
/// 2
fn add(lst: Vec<isize>) -> isize {
    lst.iter()
        .enumerate()
        .filter(|(i, v)| *i % 2 == 1 && *v % 2 == 0)
        .map(|(_, v)| *v)
        .sum()
}

fn anti_shuffle(s: String) -> String {
    s.split(' ')
        .map(|word| {
            let mut chars: Vec<char> = word.chars().collect();
            chars.sort_unstable();
            chars.into_iter().collect()
        })
        .collect::<Vec<String>>()
        .join(" ")
}

fn get_row(lst: Vec<Vec<isize>>, x: isize) -> Vec<(isize, isize)> {
    let mut result: Vec<(isize, isize)> = Vec::new();
    for (row_idx, row) in lst.iter().enumerate() {
        let mut cols: Vec<isize> = Vec::new();
        for (col_idx, val) in row.iter().enumerate() {
            if *val == x {
                cols.push(col_idx as isize);
            }
        }
        // Sort columns in descending order
        cols.sort_unstable_by(|a, b| b.cmp(a));
        for col in cols {
            result.push((row_idx as isize, col));
        }
    }
    result
}

fn sort_array(array: Vec<isize>) -> Vec<isize> {
    if array.is_empty() {
        return Vec::new();
    }

    let first = array[0];
    let last = *array.last().unwrap();
    let sum = first + last;

    let mut sorted = array.clone();

    if sum % 2 != 0 {
        // odd sum: sort ascending
        sorted.sort();
    } else {
        // even sum: sort descending
        sorted.sort();
        sorted.reverse();
    }

    sorted
}

fn encrypt(s: String) -> String {
    s.chars()
        .map(|c| {
            if c.is_ascii_lowercase() {
                let shifted = (c as u8 - b'a' + 4) % 26;
                (shifted + b'a') as char
            } else if c.is_ascii_uppercase() {
                let shifted = (c as u8 - b'A' + 4) % 26;
                (shifted + b'A') as char
            } else {
                c
            }
        })
        .collect()
}

fn next_smallest(lst: Vec<isize>) -> Option<isize> {
    if lst.len() < 2 {
        return None;
    }

    let mut min1: Option<isize> = None;
    let mut min2: Option<isize> = None;

    for &val in &lst {
        if let Some(m1) = min1 {
            if val < m1 {
                min2 = Some(m1);
                min1 = Some(val);
            } else if val != m1 {
                if let Some(m2) = min2 {
                    if val < m2 {
                        min2 = Some(val);
                    }
                } else {
                    min2 = Some(val);
                }
            }
        } else {
            min1 = Some(val);
        }
    }

    min2
}

fn is_bored(S: String) -> isize {
    let mut count: isize = 0;
    let mut at_sentence_start = true;
    for ch in S.chars() {
        if at_sentence_start {
            if ch == 'I' {
                // Check if the next character is a space or end of string
                // Actually, we need to check if "I" is the first word.
                // A sentence starts with "I" if the first non-whitespace character is 'I'
                // and it's followed by a non-alphanumeric character or end.
                // But simpler: we track if we're at the start of a sentence.
                // If the first character of the sentence is 'I', we count it.
                // But we need to make sure "I" is a whole word, not part of another word.
                // Since we're at sentence start, if ch == 'I', we need to verify it's a standalone word.
                // Let's use a different approach: split by sentence delimiters and check each sentence.
                break;
            }
        }
        if ch == '.' || ch == '?' || ch == '!' {
            at_sentence_start = true;
        } else if at_sentence_start && !ch.is_whitespace() {
            // This is the first non-whitespace character of a sentence
            if ch == 'I' {
                // Need to check if it's a standalone word "I"
                // We'll handle this with a different approach
                break;
            }
            at_sentence_start = false;
        }
    }

    // Let's use a cleaner approach: split into sentences and check each
    let sentences: Vec<&str> = S.split(['.', '?', '!']).collect();
    for sentence in sentences {
        let trimmed = sentence.trim();
        if trimmed.is_empty() {
            continue;
        }
        // Check if the sentence starts with the word "I"
        // The first word should be exactly "I"
        if let Some(first_word) = trimmed.split_whitespace().next() {
            if first_word == "I" {
                count += 1;
            }
        }
    }
    count
}

fn any_int(x: f64, y: f64, z: f64) -> bool {
    // Check if all numbers are integers
    if !x.is_integer() || !y.is_integer() || !z.is_integer() {
        return false;
    }

    // Check if one number equals the sum of the other two
    x == y + z || y == x + z || z == x + y
}

fn encode(message: String) -> String {
    let vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'];
    message
        .chars()
        .map(|c| {
            if vowels.contains(&c) {
                // Replace vowel with the letter 2 places ahead
                let code = c as u32;
                let new_code = code + 2;
                (new_code as u8) as char
            } else {
                // Swap case
                if c.is_uppercase() {
                    c.to_lowercase().next().unwrap()
                } else {
                    c.to_uppercase().next().unwrap()
                }
            }
        })
        .collect()
}

fn skjkasdkd(lst: Vec<isize>) -> isize {
    fn is_prime(n: isize) -> bool {
        if n < 2 {
            return false;
        }
        if n == 2 {
            return true;
        }
        if n % 2 == 0 {
            return false;
        }
        let mut i = 3;
        while i * i <= n {
            if n % i == 0 {
                return false;
            }
            i += 2;
        }
        true
    }

    fn digit_sum(n: isize) -> isize {
        let mut sum = 0;
        let mut n = n;
        if n < 0 {
            n = -n;
        }
        while n > 0 {
            sum += n % 10;
            n /= 10;
        }
        sum
    }

    let mut largest_prime: Option<isize> = None;
    for &val in &lst {
        if is_prime(val) {
            match largest_prime {
                None => largest_prime = Some(val),
                Some(current) => {
                    if val > current {
                        largest_prime = Some(val);
                    }
                }
            }
        }
    }

    match largest_prime {
        Some(p) => digit_sum(p),
        None => 0,
    }
}

use std::collections::HashMap;

/// Given a HashMap, return true if all keys are strings in lower 
/// case or all keys are strings in upper case, else return false.
/// The function should return false is the given HashMap is empty.
/// Examples:
/// >>> check_dict_case(HashMap::from([(String::from("a"), String::from("apple")), (String::from("b"), String::from("banana"))]))
/// true
/// >>> check_dict_case(HashMap::from([(String::from("a"), String::from("apple")), (String::from("A"), String::from("banana")), (String::from("B"), String::from("banana"))]))
/// false
/// >>> check_dict_case(HashMap::from([(String::from("a"), String::from("apple")), (8, String::from("banana")), (String::from("a"), String::from("apple"))]))
/// false
/// >>> check_dict_case(HashMap::from([(String::from("Name"), String::from("John")), (String::from("Age"), String::from("36")), (String::from("City"), String::from("Houston"))]))
/// false
/// >>> check_dict_case(HashMap::from([(String::from("STATE"), String::from("NC")), (String::from("ZIP"), String::from("12345"))]))
/// true
fn check_dict_case(dict: HashMap<String, String>) -> bool {
    if dict.is_empty() {
        return false;
    }

    let all_lower = dict.keys().all(|k| k == &k.to_lowercase());
    let all_upper = dict.keys().all(|k| k == &k.to_uppercase());

    all_lower || all_upper
}

fn count_up_to(n: isize) -> Vec<isize> {
    if n <= 1 {
        return Vec::new();
    }
    let limit = n as usize;
    let mut is_prime = vec![true; limit];
    is_prime[0] = false;
    if limit > 1 {
        is_prime[1] = false;
    }
    let mut i = 2;
    while i * i < limit {
        if is_prime[i] {
            let mut j = i * i;
            while j < limit {
                is_prime[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    let mut result = Vec::new();
    for i in 2..limit {
        if is_prime[i] {
            result.push(i as isize);
        }
    }
    result
}

