fn minSubArraySum(nums: Vec<isize>) -> isize {
    let mut min_ending_here: isize = 0;
    let mut min_so_far: isize = nums[0];

    for &num in &nums {
        min_ending_here = std::cmp::min(num, min_ending_here + num);
        min_so_far = std::cmp::min(min_so_far, min_ending_here);
    }

    min_so_far
}

fn max_fill(grid: Vec<Vec<isize>>, capacity: isize) -> isize {
    let total_water: isize = grid.iter().map(|row| row.iter().sum::<isize>()).sum();
    if total_water == 0 {
        return 0;
    }
    (total_water + capacity - 1) / capacity
}

fn sort_array(arr: Vec<isize>) -> Vec<isize> {
    let mut sorted = arr;
    sorted.sort_by(|a, b| {
        let ones_a = a.count_ones();
        let ones_b = b.count_ones();
        ones_a.cmp(&ones_b).then_with(|| a.cmp(b))
    });
    sorted
}

fn select_words(s: String, n: isize) -> Vec<String> {
    if s.is_empty() {
        return Vec::new();
    }

    let mut result = Vec::new();

    for word in s.split_whitespace() {
        let consonant_count = word
            .chars()
            .filter(|c| c.is_ascii_alphabetic())
            .filter(|c| !matches!(*c, 'a' | 'e' | 'i' | 'o' | 'u' | 'A' | 'E' | 'I' | 'O' | 'U'))
            .count() as isize;

        if consonant_count == n {
            result.push(word.to_string());
        }
    }

    result
}

fn get_closest_vowel(word: String) -> String {
    let chars: Vec<char> = word.chars().collect();
    let len = chars.len();

    if len < 3 {
        return String::new();
    }

    // Check from right to left (excluding first and last characters)
    for i in (1..len - 1).rev() {
        let c = chars[i];
        if is_vowel(c) {
            // Check if both neighbors are consonants
            if is_consonant(chars[i - 1]) && is_consonant(chars[i + 1]) {
                return c.to_string();
            }
        }
    }

    String::new()
}

fn is_vowel(c: char) -> bool {
    matches!(c, 'a' | 'e' | 'i' | 'o' | 'u' | 'A' | 'E' | 'I' | 'O' | 'U')
}

fn is_consonant(c: char) -> bool {
    c.is_ascii_alphabetic() && !is_vowel(c)
}

fn match_parens(lst: Vec<String>) -> String {
    // Check if concatenating lst[0] + lst[1] or lst[1] + lst[0] results in a balanced string.
    // A string is balanced if:
    // 1. The total number of '(' equals the total number of ')'
    // 2. At every prefix, the number of '(' is >= the number of ')'

    let s0 = &lst[0];
    let s1 = &lst[1];

    // Check if a given string is balanced
    fn is_balanced(s: &str) -> bool {
        let mut count = 0;
        for c in s.chars() {
            if c == '(' {
                count += 1;
            } else if c == ')' {
                count -= 1;
            }
            if count < 0 {
                return false;
            }
        }
        count == 0
    }

    // Try both orders
    let combined1 = format!("{}{}", s0, s1);
    let combined2 = format!("{}{}", s1, s0);

    if is_balanced(&combined1) || is_balanced(&combined2) {
        String::from("Yes")
    } else {
        String::from("No")
    }
}

fn maximum(arr: Vec<isize>, k: isize) -> Vec<isize> {
