    let k_usize = k as usize;
    let start = sorted.len().saturating_sub(k_usize);
    sorted[start..].to_vec()
}

/// Given a non-empty vector of integers arr and an integer k, return
/// the sum of the elements with at most two digits from the first k elements of arr.
/// Example:
/// >>> add_elements(vec![111, 21, 3, 4000, 5, 6, 7, 8, 9], 4)
/// 24
/// Constraints:
/// 1. 1 <= len(arr) <= 100
/// 2. 1 <= k <= len(arr)
fn add_elements(arr: Vec<isize>, k: isize) -> isize {
    let k = k as usize;
    arr.iter()
        .take(k)
        .filter(|&&x| x.abs() < 100)
        .sum()
}

fn get_odd_collatz(n: isize) -> Vec<isize> {
    let mut sequence = Vec::new();
    let mut current = n;
    loop {
        sequence.push(current);
        if current == 1 {
            break;
        }
        if current % 2 == 0 {
            current = current / 2;
        } else {
            current = 3 * current + 1;
        }
    }
    let mut odds: Vec<isize> = sequence.into_iter().filter(|&x| x % 2 != 0).collect();
    odds.sort();
    odds
}

fn valid_date(date: String) -> bool {
    // Rule 1: The date string is not empty.
    if date.is_empty() {
        return false;
    }

    // Rule 4: The date should be in the format: mm-dd-yyyy
    // Split by '-'
    let parts: Vec<&str> = date.split('-').collect();
    if parts.len() != 3 {
        return false;
    }

    let mm_str = parts[0];
    let dd_str = parts[1];
    let yyyy_str = parts[2];

    // Check that each part is exactly the right length
    if mm_str.len() != 2 || dd_str.len() != 2 || yyyy_str.len() != 4 {
        return false;
    }

    // Check that all characters are digits
    if !mm_str.chars().all(|c| c.is_ascii_digit())
        || !dd_str.chars().all(|c| c.is_ascii_digit())
        || !yyyy_str.chars().all(|c| c.is_ascii_digit())
    {
        return false;
    }

    // Parse to integers
    let mm: u32 = match mm_str.parse() {
        Ok(v) => v,
        Err(_) => return false,
    };
    let dd: u32 = match dd_str.parse() {
        Ok(v) => v,
        Err(_) => return false,
    };
    let _yyyy: u32 = match yyyy_str.parse() {
        Ok(v) => v,
        Err(_) => return false,
    };

    // Rule 3: The months should not be less than 1 or higher than 12.
    if mm < 1 || mm > 12 {
        return false;
    }

    // Rule 2: Check days based on month
    let max_days: u32 = match mm {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => 29,
        _ => return false,
    };

    if dd < 1 || dd > max_days {
        return false;
    }

    true
}

fn is_sorted(lst: Vec<isize>) -> bool {
    if lst.len() <= 1 {
        return true;
    }
    let mut prev = lst[0];
    let mut prev_count = 1;
    for i in 1..lst.len() {
        let curr = lst[i];
        if curr < prev {
            return false;
        }
        if curr == prev {
            prev_count += 1;
            if prev_count > 2 {
                return false;
            }
        } else {
            prev = curr;
            prev_count = 1;
        }
    }
    true
}

fn intersection(interval1: (isize, isize), interval2: (isize, isize)) -> String {
    let (start1, end1) = interval1;
    let (start2, end2) = interval2;

    // Compute the intersection
    let inter_start = std::cmp::max(start1, start2);
    let inter_end = std::cmp::min(end1, end2);

    // If no intersection, return "NO"
    if inter_start > inter_end {
        return String::from("NO");
    }

    // Length of intersection (number of integer points in the closed interval)
    let length = inter_end - inter_start + 1;

    // Check if length is prime
    if is_prime(length) {
        String::from("YES")
    } else {
        String::from("NO")
    }
}

fn is_prime(n: isize) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

/// You are given a vector arr of integers and you need to return
/// sum of magnitudes of integers multiplied by product of all signs
/// of each number in the vector, represented by 1, -1 or 0.
/// Note: return None for empty arr.
/// Example:
/// >>> prod_signs(vec![1, 2, 2, -4])
/// Some(9)
/// >>> prod_signs(vec![0, 1])
/// Some(0)
/// >>> prod_signs(vec![])
/// None
fn prod_signs(arr: Vec<isize>) -> Option<isize> {
    if arr.is_empty() {
        return None;
    }

    let sum_magnitudes: isize = arr.iter().map(|x| x.abs()).sum();
    let product_signs: isize = arr.iter().map(|x| {
        if *x > 0 {
            1
        } else if *x < 0 {
            -1
        } else {
            0
        }
    }).product();

    Some(sum_magnitudes * product_signs)
}

