fn tri(n: isize) -> Vec<isize> {
    if n < 0 {
        return vec![];
    }

    // We need to compute tri(0) through tri(n)
    // tri(1) = 3
    // tri(n) = 1 + n/2 if n is even
    // tri(n) = tri(n-1) + tri(n-2) + tri(n+1) if n is odd

    // Note: tri(0) is not explicitly defined in the problem, but the example shows
    // tri(3) returns vec![1, 3, 2, 8], which means:
    // index 0: 1
    // index 1: 3
    // index 2: 2
    // index 3: 8
    // So tri(0) = 1, tri(1) = 3, tri(2) = 2, tri(3) = 8

    // Let's figure out the pattern:
    // tri(0) = 1 (from example)
    // tri(1) = 3 (given)
    // tri(2) = 1 + 2/2 = 2 (even formula)
    // tri(3) = tri(2) + tri(1) + tri(4) = 2 + 3 + tri(4)
    // tri(4) = 1 + 4/2 = 3 (even formula)
    // So tri(3) = 2 + 3 + 3 = 8 ✓

    // For odd n > 1: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
    // But tri(n+1) when n+1 is even can be computed directly.
    // So for odd n: tri(n) = tri(n-1) + tri(n-2) + (1 + (n+1)/2)

    // Let's build the vector from 0 to n.
    let size = (n + 1) as usize;
    let mut result = vec![0; size];

    // tri(0) = 1
    result[0] = 1;

    if n >= 1 {
        result[1] = 3;
    }

    for i in 2..=n {
        if i % 2 == 0 {
            // even: tri(i) = 1 + i/2
            result[i as usize] = 1 + i / 2;
        } else {
            // odd: tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
            // tri(i+1) is even, so tri(i+1) = 1 + (i+1)/2
            let tri_i_plus_1 = 1 + (i + 1) / 2;
            result[i as usize] = result[(i - 1) as usize] + result[(i - 2) as usize] + tri_i_plus_1;
        }
    }

    result
}

/// Given a positive integer n, return the product of the odd digits.
/// Return 0 if all digits are even.
/// For example:
/// >>> digits(1)
/// 1
/// >>> digits(4)
/// 0
/// >>> digits(235)
/// 15
fn digits(n: isize) -> isize {
    let mut product: isize = 1;
    let mut has_odd = false;
    let mut num = n;
    while num > 0 {
        let digit = num % 10;
        if digit % 2 != 0 {
            product *= digit;
            has_odd = true;
        }
        num /= 10;
    }
    if has_odd {
        product
    } else {
        0
    }
}

