fn largest_smallest_integers(lst: Vec<isize>) -> (Option<isize>, Option<isize>) {
    let mut largest_negative: Option<isize> = None;
    let mut smallest_positive: Option<isize> = None;

    for &x in &lst {
        if x < 0 {
            match largest_negative {
                None => largest_negative = Some(x),
                Some(current) => {
                    if x > current {
                        largest_negative = Some(x);
                    }
                }
            }
        } else if x > 0 {
            match smallest_positive {
                None => smallest_positive = Some(x),
                Some(current) => {
                    if x < current {
                        smallest_positive = Some(x);
                    }
                }
            }
        }
    }

    (largest_negative, smallest_positive)
}

/// Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers
/// Example
/// >>> is_equal_to_sum_even(4)
/// false
/// >>> is_equal_to_sum_even(6)
/// false
/// >>> is_equal_to_sum_even(8)
/// true
fn is_equal_to_sum_even(n: isize) -> bool {
    // We need to write n as the sum of exactly 4 positive even numbers.
    // Each positive even number is at least 2.
    // So the minimum sum is 2 + 2 + 2 + 2 = 8.
    // Also, the sum of 4 even numbers is always even.
    // So n must be even and n >= 8.
    // Let's verify: if n is even and n >= 8, can we always find 4 positive even numbers that sum to n?
    // Let the four numbers be a, b, c, d, each >= 2 and even.
    // Let a = 2, b = 2, c = 2, d = n - 6.
    // For d to be a positive even number, we need n - 6 >= 2 and n - 6 even.
    // n - 6 >= 2 means n >= 8.
    // n - 6 even means n is even (since 6 is even).
    // So if n is even and n >= 8, we can set a=2, b=2, c=2, d=n-6, and d is a positive even number.
    // Thus the condition is: n is even and n >= 8.
    n >= 8 && n % 2 == 0
}

/// The Brazilian factorial is defined as:
/// brazilian_factorial(n) = n! * (n-1)! * (n-2)! * ... * 1!
/// where n > 0
/// For example:
/// >>> special_factorial(4)
/// 288
/// The function will receive an integer as input and should return the special
/// factorial of this integer.
fn special_factorial(n: isize) -> isize {
    let mut result: isize = 1;
    let mut factorial: isize = 1;
    for i in 1..=n {
        factorial *= i;
        result *= factorial;
    }
    result
}

fn fix_spaces(text: String) -> String {
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    let mut result = String::new();
    let mut i = 0;
    while i < n {
        if chars[i] == ' ' {
            // Count consecutive spaces
            let mut j = i;
            while j < n && chars[j] == ' ' {
                j += 1;
            }
            let count = j - i;
            if count > 2 {
                result.push('-');
            } else {
                for _ in 0..count {
                    result.push('_');
                }
            }
            i = j;
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    result
}

fn file_name_check(file_name: String) -> String {
    // Check exactly one dot
    let dot_count = file_name.matches('.').count();
    if dot_count != 1 {
        return String::from("No");
    }

    // Split into name and extension
    let dot_pos = file_name.find('.').unwrap();
    let name_part = &file_name[..dot_pos];
    let ext_part = &file_name[dot_pos + 1..];

    // Check name part is not empty and starts with a letter
    if name_part.is_empty() {
        return String::from("No");
    }
    let first_char = name_part.chars().next().unwrap();
    if !first_char.is_ascii_alphabetic() {
        return String::from("No");
    }

    // Check extension is one of the valid ones
    if ext_part != "txt" && ext_part != "exe" && ext_part != "dll" {
        return String::from("No");
    }

    // Check no more than three digits in the entire file name
    let digit_count = file_name.chars().filter(|c| c.is_ascii_digit()).count();
    if digit_count > 3 {
        return String::from("No");
    }

    String::from("Yes")
}

