    lst.iter().enumerate().map(|(i, &x)| {
        if i % 3 == 0 {
            x * x
        } else if i % 4 == 0 {
            x * x * x
        } else {
            x
        }
    }).sum()
}

fn words_in_sentence(sentence: String) -> String {
    fn is_prime(n: usize) -> bool {
        if n < 2 {
            return false;
        }
        if n == 2 {
            return true;
        }
        if n % 2 == 0 {
            return false;
        }
        let mut i = 3;
        while i * i <= n {
            if n % i == 0 {
                return false;
            }
            i += 2;
        }
        true
    }

    let words: Vec<&str> = sentence.split_whitespace().collect();
    let result: Vec<&str> = words
        .iter()
        .filter(|w| is_prime(w.len()))
        .copied()
        .collect();
    result.join(" ")
}

fn simplify(x: String, n: String) -> bool {
    // Parse the fractions
    let parse_fraction = |s: &str| -> (u64, u64) {
        let parts: Vec<&str> = s.split('/').collect();
        let numerator: u64 = parts[0].parse().unwrap();
        let denominator: u64 = parts[1].parse().unwrap();
        (numerator, denominator)
    };

    let (x_num, x_den) = parse_fraction(&x);
    let (n_num, n_den) = parse_fraction(&n);

    // Compute x * n = (x_num * n_num) / (x_den * n_den)
    // We need to check if this is a whole number, i.e., (x_num * n_num) % (x_den * n_den) == 0
    // But we need to be careful about overflow. Let's use a smarter approach.
    //
    // x * n = (x_num / x_den) * (n_num / n_den) = (x_num * n_num) / (x_den * n_den)
    //
    // For this to be a whole number, (x_num * n_num) must be divisible by (x_den * n_den).
    //
    // To avoid overflow, we can simplify the fraction first by canceling common factors.
    // Let's compute the product and check divisibility using GCD to reduce.

    // Compute numerator = x_num * n_num, denominator = x_den * n_den
    // But to avoid overflow, let's reduce the fraction step by step.

    // First, reduce x_num/x_den and n_num/n_den individually? No, we need the product.
    // Let's compute the product fraction and reduce it.

    // numerator = x_num * n_num
    // denominator = x_den * n_den

    // We can reduce by finding GCDs:
    // Let g1 = gcd(x_num, x_den), reduce x
    // Let g2 = gcd(n_num, n_den), reduce n
    // Then multiply the reduced fractions.

    // Actually, let's just compute the product and check if it's an integer.
    // To handle potential overflow, we can use the fact that:
    // (x_num * n_num) / (x_den * n_den) is an integer iff
    // (x_num * n_num) % (x_den * n_den) == 0

    // But x_num * n_num and x_den * n_den could overflow u64.
    // Let's use a different approach: reduce the fraction before multiplying.

    // Reduce x_num/x_den
    let gcd = |a: u64, b: u64| -> u64 {
        if b == 0 { a } else { gcd(b, a % b) }
    };

    let g1 = gcd(x_num, x_den);
    let x_num_reduced = x_num / g1;
    let x_den_reduced = x_den / g1;

    let g2 = gcd(n_num, n_den);
    let n_num_reduced = n_num / g2;
    let n_den_reduced = n_den / g2;

    // Now multiply: (x_num_reduced * n_num_reduced) / (x_den_reduced * n_den_reduced)
    // We can further reduce by cross-canceling:
    // Let g3 = gcd(x_num_reduced, n_den_reduced)
    // Let g4 = gcd(n_num_reduced, x_den_reduced)

    let g3 = gcd(x_num_reduced, n_den_reduced);
    let x_num_reduced2 = x_num_reduced / g3;
    let n_den_reduced2 = n_den_reduced / g3;

    let g4 = gcd(n_num_reduced, x_den_reduced);
    let n_num_reduced2 = n_num_reduced / g4;
    let x_den_reduced2 = x_den_reduced / g4;

    // Now the fraction is (x_num_reduced2 * n_num_reduced2) / (x_den_reduced2 * n_den_reduced2)
    // For this to be a whole number, the denominator must divide the numerator.
    // Since we've reduced as much as possible, the denominator should be 1 for it to be a whole number.
    // Wait, that's not quite right. The denominator after reduction should be 1.

    // Actually, after all reductions, the fraction is in lowest terms.
    // So the result is a whole number iff the denominator is 1.

    let final_den = x_den_reduced2 * n_den_reduced2;
    final_den == 1
}

fn order_by_points(nums: Vec<isize>) -> Vec<isize> {
    let mut indexed: Vec<(usize, isize)> = nums.iter().enumerate().map(|(i, &v)| (i, v)).collect();
    indexed.sort_by_key(|&(i, v)| (digit_sum(v), i));
    indexed.into_iter().map(|(_, v)| v).collect()
}

fn digit_sum(n: isize) -> usize {
    let mut sum = 0;
    let mut x = n.unsigned_abs();
    while x > 0 {
        sum += (x % 10) as usize;
        x /= 10;
    }
    sum
}

fn specialFilter(nums: Vec<isize>) -> isize {
    nums.iter()
        .filter(|&&n| {
            if n <= 10 {
                return false;
            }
            let abs_n = n.abs();
            let last_digit = abs_n % 10;
            // Find first digit
            let mut first_digit = abs_n;
            while first_digit >= 10 {
                first_digit /= 10;
            }
            let is_odd = |d: isize| d % 2 != 0;
            is_odd(first_digit) && is_odd(last_digit)
        })
        .count() as isize
}

fn get_max_triples(n: isize) -> isize {
    // For each i (1-indexed), a[i] = i*i - i + 1
    // We need to count triples (i, j, k) with i < j < k such that a[i] + a[j] + a[k] % 3 == 0

    // Let's analyze a[i] mod 3:
    // a[i] = i^2 - i + 1
    // i mod 3:
    // i = 0: 0 - 0 + 1 = 1 mod 3
    // i = 1: 1 - 1 + 1 = 1 mod 3
    // i = 2: 4 - 2 + 1 = 3 = 0 mod 3
    // i = 3: 9 - 3 + 1 = 7 = 1 mod 3
    // i = 4: 16 - 4 + 1 = 13 = 1 mod 3
    // i = 5: 25 - 5 + 1 = 21 = 0 mod 3
    // i = 6: 36 - 6 + 1 = 31 = 1 mod 3
    // i = 7: 49 - 7 + 1 = 43 = 1 mod 3
    // i = 8: 64 - 8 + 1 = 57 = 0 mod 3
    // i = 9: 81 - 9 + 1 = 73 = 1 mod 3
    // i = 10: 100 - 10 + 1 = 91 = 1 mod 3
    // i = 11: 121 - 11 + 1 = 111 = 0 mod 3

    // So the pattern for i mod 3:
    // i mod 3 == 0: a[i] mod 3 = 1
    // i mod 3 == 1: a[i] mod 3 = 1
    // i mod 3 == 2: a[i] mod 3 = 0

    // Wait, let me recheck:
    // i=1: 1*1-1+1=1, 1 mod 3 = 1
    // i=2: 2*2-2+1=3, 3 mod 3 = 0
    // i=3: 3*3-3+1=7, 7 mod 3 = 1
    // i=4: 4*4-4+1=13, 13 mod 3 = 1
    // i=5: 5*5-5+1=21, 21 mod 3 = 0
    // i=6: 6*6-6+1=31, 31 mod 3 = 1
    // i=7: 7*7-7+1=43, 43 mod 3 = 1
    // i=8: 8*8-8+1=57, 57 mod 3 = 0
    // i=9: 9*9-9+1=73, 73 mod 3 = 1
    // i=10: 10*10-10+1=91, 91 mod 3 = 1
    // i=11: 11*11-11+1=111, 111 mod 3 = 0

    // So:
    // i mod 3 == 1: a[i] mod 3 = 1
    // i mod 3 == 2: a[i] mod 3 = 0
    // i mod 3 == 0: a[i] mod 3 = 1

    // So a[i] mod 3 is:
    // 1 if i mod 3 is 0 or 1
    // 0 if i mod 3 is 2

    // We need a[i] + a[j] + a[k] ≡ 0 (mod 3)
    // Possible combinations of residues (r1, r2, r3) where each is 0 or 1:
    // (0,0,0): sum = 0 ✓
    // (0,0,1): sum = 1 ✗
    // (0,1,0): sum = 1 ✗
    // (1,0,0): sum = 1 ✗
    // (0,1,1): sum = 2 ✗
    // (1,0,1): sum = 2 ✗
    // (1,1,0): sum = 2 ✗
    // (1,1,1): sum = 3 ≡ 0 ✓

    // So valid triples are:
    // 1. All three have residue 0 (i.e., i, j, k all ≡ 2 mod 3)
    // 2. All three have residue 1 (i.e., i, j, k all ≡ 0 or 1 mod 3)

    // Let's count:
    // Let c0 = number of i in [1, n] with i mod 3 == 2 (residue 0)
    // Let c1 = number of i in [1, n] with i mod 3 == 0 or 1 (residue 1)

    // c0 = floor((n - 2) / 3) + 1 if n >= 2, else 0
    // More precisely: count of numbers in [1, n] congruent to 2 mod 3
    // These are: 2, 5, 8, ..., up to n
    // c0 = if n < 2 { 0 } else { (n - 2) / 3 + 1 }

    // c1 = n - c0

    // Number of triples with all residue 0: C(c0, 3)
    // Number of triples with all residue 1: C(c1, 3)

    // Total = C(c0, 3) + C(c1, 3)

    let c0: isize;
    if n < 2 {
        c0 = 0;
    } else {
        c0 = (n - 2) / 3 + 1;
    }
    let c1 = n - c0;

    let comb3 = |x: isize| -> isize {
        if x < 3 {
            0
        } else {
            x * (x - 1) * (x - 2) / 6
        }
    };

    comb3(c0) + comb3(c1)
}

fn sorted_list_sum(lst: Vec<String>) -> Vec<String> {
    let mut result: Vec<String> = lst
        .into_iter()
        .filter(|s| s.len() % 2 == 0)
        .collect();
    result.sort_by(|a, b| {
        a.len()
            .cmp(&b.len())
            .then_with(|| a.cmp(b))
    });
    result
}

fn x_or_y(n: isize, x: isize, y: isize) -> isize {
    if is_prime(n) {
        x
    } else {
        y
    }
}

fn is_prime(n: isize) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

fn compare(game: Vec<isize>, guess: Vec<isize>) -> Vec<isize> {
    game.iter()
        .zip(guess.iter())
        .map(|(&g, &gu)| (g - gu).abs())
        .collect()
}

fn Strongest_Extension(class_name: String, extensions: Vec<String>) -> String {
    let mut best_idx: usize = 0;
    let mut best_strength: i32 = i32::MIN;

    for (i, ext) in extensions.iter().enumerate() {
        let cap: i32 = ext.chars().filter(|c| c.is_uppercase()).count() as i32;
        let sm: i32 = ext.chars().filter(|c| c.is_lowercase()).count() as i32;
        let strength = cap - sm;
        if strength > best_strength {
            best_strength = strength;
            best_idx = i;
        }
    }

    format!("{}.{}", class_name, extensions[best_idx])
}

fn cycpattern_check(a: String, b: String) -> bool {
    if b.is_empty() {
        return true;
    }
    if b.len() > a.len() {
        return false;
    }
    // Generate all rotations of b and check if any is a substring of a
    let b_len = b.len();
    for i in 0..b_len {
        let rotation = &b[i..] + &b[..i];
        if a.contains(rotation) {
            return true;
        }
    }
    false
}

/// Given an integer. return a tuple that has the number of even and odd digits respectively.
/// Example:
/// >>> even_odd_count(-12)
/// (1, 1)
/// >>> even_odd_count(123)
/// (1, 2)
fn even_odd_count(num: isize) -> (isize, isize) {
    let mut even_count: isize = 0;
    let mut odd_count: isize = 0;
    let mut n = num;
    if n == 0 {
        // 0 is even
        even_count = 1;
        return (even_count, odd_count);
    }
    while n != 0 {
        let digit = (n % 10).abs();
        if digit % 2 == 0 {
            even_count += 1;
        } else {
            odd_count += 1;
        }
        n /= 10;
    }
    (even_count, odd_count)
}

fn int_to_mini_roman(number: isize) -> String {
    let mut num = number;
    let mut result = String::new();

    let values = [
        (1000, "m"),
        (900, "cm"),
        (500, "d"),
        (400, "cd"),
        (100, "c"),
        (90, "xc"),
        (50, "l"),
        (40, "xl"),
        (10, "x"),
        (9, "ix"),
        (5, "v"),
        (4, "iv"),
        (1, "i"),
    ];

    for (value, symbol) in values {
        while num >= value {
            result.push_str(symbol);
            num -= value;
        }
    }

    result
}

fn right_angle_triangle(a: isize, b: isize, c: isize) -> bool {
    let mut sides = [a, b, c];
    sides.sort_unstable();
    let (x, y, z) = (sides[0], sides[1], sides[2]);
    x > 0 && y > 0 && z > 0 && x * x + y * y == z * z
}

fn find_max(words: Vec<String>) -> String {
    use std::collections::HashSet;

    let mut best: Option<String> = None;
    let mut best_count: usize = 0;

    for word in &words {
        let unique_count = word.chars().collect::<HashSet<char>>().len();
        if unique_count > best_count {
            best_count = unique_count;
            best = Some(word.clone());
        } else if unique_count == best_count {
            if let Some(ref b) = best {
                if word < b {
                    best = Some(word.clone());
                }
            }
        }
    }

    best.unwrap_or_default()
}

fn eat(number: isize, need: isize, remaining: isize) -> Vec<isize> {
    let eaten = need.min(remaining);
    let total = number + eaten;
    let left = remaining - eaten;
    vec![total, left]
}

fn do_algebra(operator: Vec<String>, operand: Vec<isize>) -> isize {
    let mut result = operand[0];
    for (i, op) in operator.iter().enumerate() {
        let next = operand[i + 1];
        result = match op.as_str() {
            "+" => result + next,
            "-" => result - next,
            "*" => result * next,
            "//" => result / next,
            "**" => result.pow(next as u32),
            _ => panic!("Unknown operator: {}", op),
        };
    }
    result
}

fn solve(s: String) -> String {
    let has_letters = s.chars().any(|c| c.is_alphabetic());
    if has_letters {
        s.chars()
            .map(|c| {
                if c.is_lowercase() {
                    c.to_uppercase().to_string()
                } else if c.is_uppercase() {
                    c.to_lowercase().to_string()
                } else {
                    c.to_string()
                }
            })
            .collect()
    } else {
        s.chars().rev().collect()
    }
}

use md5::{Md5, Digest};

/// Given a string 'text', return its md5 hash equivalent string.
/// If 'text' is an empty string, return None.
/// >>> string_to_md5(String::from("Hello world"))
/// Some(String::from("3e25960a79dbc69b674cd4ec67a72c62"))
fn string_to_md5(text: String) -> Option<String> {
    if text.is_empty() {
        return None;
    }
    let mut hasher = Md5::new();
    hasher.update(text.as_bytes());
    let result = hasher.finalize();
    let hex_string = format!("{:x}", result);
    Some(hex_string)
}

fn generate_integers(a: isize, b: isize) -> Vec<isize> {
    let start = a.min(b);
    let end = a.max(b);
    (start..=end)
        .filter(|&x| x % 2 == 0)
        .collect()
}
